// Code generated by server/cmd/apicodes. DO NOT EDIT.
//
// The codes the Chirp API can return. `CODE_MESSAGES` in ./api-messages.ts
// is typed against this list, so the compiler fails when a code is added
// on the server without a message on the client.
//
// Run `task.ps1 generate` to refresh this file.

export const API_CODES = [
  'already_verified',
  'challenge_locked',
  'email_in_use',
  'email_not_verified',
  'internal_error',
  'invalid_code',
  'invalid_credentials',
  'invalid_provider_token',
  'invalid_session',
  'no_pending_verification',
  'password_already_set',
  'provider_email_unverified',
  'provider_no_email',
  'provider_unavailable',
  'resend_limit',
  'resend_too_soon',
  'service_unavailable',
  'session_revoked',
  'social_conflict',
  'social_not_configured',
  'user_not_found',
  'username_already_set',
  'username_taken',
  'validation_failed',
] as const;

export type ApiCode = (typeof API_CODES)[number];

/** Narrows an unknown string to a code the API can return. */
export function isApiCode(value: string): value is ApiCode {
  return (API_CODES as readonly string[]).includes(value);
}
